mapper.select:
SELECT c.chunk_id, d.document_id, d.title, c.chunk_no, c.page_start, c.page_end, c.chunk_text
FROM ai_knowledge_chunk c JOIN ai_knowledge_document d ON d.document_id=c.document_id
WHERE c.chunk_id IN

  #{chunkId}

  AND d.deleted=0 AND d.status='READY'
  AND (d.visible_roles='ALL'

    OR (

        FIND_IN_SET(#{role}, d.visible_roles) > 0

    )
  )
